#include <WiFi.h>
#include <WiFiUdp.h>

WiFiUDP udp;
constexpr uint16_t LOCAL_PORT = 4210;
char packet[128];

void setup() {
  Serial.begin(115200);
  WiFi.mode(WIFI_STA);
  WiFi.begin("YOUR_WIFI_NAME", "YOUR_WIFI_PASSWORD");
  while (WiFi.status() != WL_CONNECTED) delay(250);
  if (!udp.begin(LOCAL_PORT)) {
    Serial.println("UDP bind failed");
  }
}

void loop() {
  const int packetSize = udp.parsePacket();
  if (packetSize <= 0) return;
  const int count = udp.read(packet, sizeof(packet) - 1);
  if (count <= 0) return;
  packet[count] = '\0';
  Serial.println(packet);
  udp.beginPacket(udp.remoteIP(), udp.remotePort());
  udp.write(reinterpret_cast<const uint8_t*>("ack"), 3);
  if (udp.endPacket() == 0) {
    Serial.println("UDP reply failed");
  }
}

#include <WiFi.h>
#include <WiFiUdp.h>
#include <NTPClient.h>

WiFiUDP ntpTransport;
NTPClient clockClient(ntpTransport, "pool.ntp.org", 0, 60000);

void setup() {
  Serial.begin(115200);
  WiFi.mode(WIFI_STA);
  WiFi.begin("YOUR_WIFI_NAME", "YOUR_WIFI_PASSWORD");
  while (WiFi.status() != WL_CONNECTED) delay(250);
  clockClient.begin();
}

void loop() {
  if (clockClient.update()) {
    Serial.println(clockClient.getFormattedTime());
  }
  delay(1000);
}
